<?php
require __DIR__.'/ui.php';role(['admin','gerente','producao']);$p=db();$rows=$p->query("SELECT sm.*,p.name,u.name user_name FROM stock_movements sm JOIN products p ON p.id=sm.product_id LEFT JOIN users u ON u.id=sm.user_id ORDER BY sm.id DESC LIMIT 500")->fetchAll();page_head('Movimentações de estoque');?>
<div class="card"><div class="table"><table><tr><th>Data</th><th>Produto</th><th>Tipo</th><th>Qtd.</th><th>Motivo</th><th>Referência</th><th>Usuário</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['name'])?></td><td><?=e($r['type'])?></td><td><?=$r['qty']?></td><td><?=e($r['reason'])?></td><td><?=e($r['reference_type'])?> #<?=e($r['reference_id'])?></td><td><?=e($r['user_name'])?></td></tr><?php endforeach;?></table></div></div><?php page_foot();?>